-- ═════════════════════════════════════════════════════════════════════════════
-- Trois pistes de programmation : `functional`, `hybrid`, `musculation`.
--
-- Le lot J1 avait livré deux pistes, dont une nommée « Functional / Hybrid ».
-- Functional et Hybrid sont deux disciplines distinctes dans le générateur
-- athlète ; elles le deviennent dans la programmation de box, activables
-- séparément. Aucune box n'est migrée : celles qui ont `{functional, musculation}`
-- gardent exactement ces deux pistes, Hybrid se coche depuis le Manager.
--
-- Appliquée en prod : NON.
--
-- Additif et rejouable :
--   1. CHECK de `boxes.auto_programming_tracks` et de `box_auto_programming_runs.track`
--      élargis à `{functional, hybrid, musculation}`.
--   2. Les 6 squelettes de séance existants (S1–S6) reçoivent `track: 'functional'`
--      dans leur `definition` — sans lui, les 7 squelettes Hybrid ajoutés ci-dessous
--      entreraient en collision sur le même jour (`day`).
--   3. Les 7 squelettes Hybrid (H1–H6 plus la simulation complète du samedi, tirée
--      une semaine sur huit) sont insérés en `discipline = 'session'`, version 3.
--   4. Banque Hybrid partagée : `engine_negative_split` ajouté et durées de
--      `engine_continuous` élargies à 35 et 40 minutes. Le jeudi de la piste n'avait
--      qu'une combinaison possible (signature répétée) et aucune durée entre 30 et 45 ;
--      le générateur athlète y gagne la même variété.
--   5. Le groupe de messages « Functional / Hybrid » est renommé « Functional » ;
--      le groupe « Hybrid » sera créé par `ensureGroup` au premier run de la piste.
--
-- GÉNÉRÉ avec les helpers de packages/wod-engine/scripts/export-bank.ts. Contrôlé
-- par packages/wod-engine/__tests__/seed-sync.test.ts.
-- ═════════════════════════════════════════════════════════════════════════════

-- ─── 1. Pistes autorisées ────────────────────────────────────────────────────
ALTER TABLE public.boxes DROP CONSTRAINT IF EXISTS boxes_auto_programming_tracks_check;
ALTER TABLE public.boxes ADD CONSTRAINT boxes_auto_programming_tracks_check
  CHECK (auto_programming_tracks <@ ARRAY['functional','hybrid','musculation']::text[]);

ALTER TABLE public.box_auto_programming_runs DROP CONSTRAINT IF EXISTS box_auto_programming_runs_track_check;
ALTER TABLE public.box_auto_programming_runs ADD CONSTRAINT box_auto_programming_runs_track_check
  CHECK (track IN ('functional','hybrid','musculation'));

COMMENT ON COLUMN public.boxes.auto_programming_tracks IS
  'Pistes générées quand auto_programming est vrai : functional (séance A/B/C 60 min, lun→sam), hybrid (course, stations et ergs, lun→sam) et/ou musculation (5 séances).';

-- ─── 2. Les six squelettes Functional reçoivent leur piste ───────────────────
